c031.try_sql:
-- Without an alias on the shared column it works; with an alias (e.department_id) it is an error
SELECT department_id, e.last_name, d.department_name
FROM   employees e JOIN departments d USING (department_id)
WHERE  department_id = 10;
SELECT e.department_id, e.last_name
FROM   employees e NATURAL JOIN departments d;

c310.try_sql:
-- USING: one copy without an alias; ON: a column without an alias is ambiguous (error)
SELECT department_id, d.department_name FROM employees e JOIN departments d USING (department_id) WHERE e.employee_id = 100;
SELECT department_id, d.department_name FROM employees e JOIN departments d ON e.department_id = d.department_id;

c1350.try_sql:
-- SELECT * works (department_id once, first), e.* raises an error
SELECT * FROM employees e JOIN departments d USING (department_id) WHERE e.employee_id = 100;
SELECT e.* FROM employees e JOIN departments d USING (department_id);

c1353.try_sql:
-- < gives each pair once; <> gives each pair twice
SELECT a.employee_id AS a_id, b.employee_id AS b_id, a.salary
FROM   employees a JOIN employees b ON a.salary = b.salary AND a.employee_id < b.employee_id;
SELECT a.employee_id AS a_id, b.employee_id AS b_id, a.salary
FROM   employees a JOIN employees b ON a.salary = b.salary AND a.employee_id <> b.employee_id;

c1357.try_sql:
-- Product 15 has list_price NULL: its line (1004/2) matches neither < nor >=
SELECT oi.order_id, oi.line_no, oi.product_id, oi.unit_price, p.list_price
FROM   order_items oi JOIN products p ON p.product_id = oi.product_id AND oi.unit_price < p.list_price;
SELECT oi.order_id, oi.line_no, oi.product_id, oi.unit_price, p.list_price
FROM   order_items oi JOIN products p ON p.product_id = oi.product_id AND oi.unit_price >= p.list_price;
